mapper.select:
select detail.*, task.mat_code
from qms_inspection_product_task task
         LEFT JOIN qms_inspection_product_task_detail detail on task.id = detail.task_id
where check_type = 'RANG'
  and task.mat_code = #{spc.matCode}
  and detail.name = #{spc.testName}
  and task.create_time <= #{spc.endTime}
  and task.create_time >= #{spc.startTime}
